-- All fixture writes are rolled back. Run this entire file, never selected statements.
BEGIN;
DO $test$
DECLARE ids uuid[];a uuid;b uuid;c uuid;d uuid;e uuid;f uuid;sid uuid;sid2 uuid;rid uuid;rid2 uuid;iv bigint;room uuid;j jsonb;failed boolean;n integer;legacy jsonb;
BEGIN
 SELECT array_agg(id) INTO ids FROM (SELECT id FROM public.profiles p WHERE NOT coalesce(banned,false) AND NOT EXISTS(SELECT 1 FROM public.squad_members WHERE user_id=p.id) ORDER BY id LIMIT 6)q;
 ASSERT cardinality(ids)=6,'Need six rollback fixture accounts';a:=ids[1];b:=ids[2];c:=ids[3];d:=ids[4];e:=ids[5];f:=ids[6];
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 INSERT INTO public.squad_creators(user_id) VALUES(a) ON CONFLICT DO NOTHING;
 j:=public.xr_sf_squad_create('__SF_PRIVATE_TEST_'||substr(a::text,1,8),'TEST','Rollback fixture','private');ASSERT (j->>'ok')::boolean,j::text;sid:=(j->>'id')::uuid;
 ASSERT length(j->>'squad_code')=10,'Code length';
 ASSERT (public.xr_sf_squad_get(sid)->'squad'->>'is_captain')::boolean,'Captain recognized';
 ASSERT (public.xr_sf_squad_settings(sid,'{"max_members":2,"roles_needed":["Rusher"],"mode":"BR","region":"Test"}')->>'ok')::boolean,'settings';
 ASSERT (public.xr_sf_player_preferences('{"combat_role":"IGL","mic":true,"languages":["Hindi","English"],"primary_language":"Hindi","discoverable":true}')->>'ok')::boolean,'Prefs';
 failed:=false;BEGIN PERFORM public.xr_sf_player_preferences('{"trust_score":99}');EXCEPTION WHEN OTHERS THEN failed:=true;END;ASSERT failed,'Trust self-write blocked';
 failed:=false;BEGIN PERFORM public.xr_sf_player_preferences('{"availability_timezone":"Invented/Zone"}');EXCEPTION WHEN OTHERS THEN failed:=true;END;ASSERT failed,'Bad timezone rejected';
 ASSERT public.xr_sf_player_get(a)->'player'->'trust_score'='null'::jsonb,'Trust not fabricated';
 ASSERT public.xr_sf_player_get(a)->'player'->'compatibility'='null'::jsonb,'Compatibility not fabricated';
 ASSERT (public.xr_sf_presence_set('in_match')->>'ok')::boolean,'presence';
 ASSERT public.xr_sf_player_get(a)->'player'->>'presence'='in_match','own in_match';
 UPDATE public.xr_sf_presence SET expires_at=now()-interval '1 second' WHERE user_id=a;
 ASSERT public.xr_sf_player_get(a)->'player'->>'presence'<>'in_match','Stale in_match expires';
 ASSERT NOT (public.xr_sf_chat_post(sid,'No production send')->>'ok')::boolean,'Chat OFF';
 ASSERT NOT EXISTS(SELECT 1 FROM public.xr_sf_chat_messages),'Chat no writes';
 ASSERT (public.xr_sf_plan_save(sid,'Test plan',0)->>'ok')::boolean,'Plan save';
 ASSERT NOT (public.xr_sf_plan_save(sid,'Stale edit',0)->>'ok')::boolean,'Plan revision check';
 PERFORM set_config('request.jwt.claim.sub',b::text,true);
 j:=public.xr_sf_squad_get(sid);ASSERT (j->>'ok')::boolean,'Private discoverable card';ASSERT j->'squad'->'squad_code'='null'::jsonb,'Private code redacted';ASSERT jsonb_array_length(j->'squad'->'members')=0,'Private roster redacted';
 ASSERT NOT (public.squad_profile(sid)->>'ok')::boolean,'Legacy profile hardened';
 ASSERT NOT (public.join_squad(sid)->>'ok')::boolean,'Legacy join hardened';
 ASSERT NOT (public.xr_sf_join_public(sid)->>'ok')::boolean,'Public join private blocked';
 ASSERT NOT EXISTS(SELECT 1 FROM public.squads_public WHERE id=sid),'View excludes private';
 ASSERT public.squad_board()::text NOT LIKE '%__SF_PRIVATE_TEST_%','Board excludes private';
 ASSERT public.squad_battle_board()::text NOT LIKE '%__SF_PRIVATE_TEST_%','Battle board excludes private';
 failed:=false;BEGIN PERFORM public.xr_sf_plan_get(sid);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;ASSERT failed,'Private plan denied';
 failed:=false;BEGIN PERFORM public.xr_sf_squad_settings(sid,'{"visibility":"public"}');EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;ASSERT failed,'Noncaptain settings denied';
 PERFORM public.xr_sf_player_preferences('{"combat_role":"Rusher","mic":true,"languages":["Hinglish"],"discoverable":true}');
 j:=public.xr_sf_join_request(sid,'Test request');ASSERT (j->>'ok')::boolean,j::text;rid:=(j->'request'->>'id')::uuid;
 ASSERT jsonb_array_length(public.xr_sf_request_list()->'requests')=1,'Own pending view';
 PERFORM set_config('request.jwt.claim.sub',c::text,true);
 ASSERT jsonb_array_length(public.xr_sf_request_list()->'requests')=0,'Other pending private';
 failed:=false;BEGIN PERFORM public.xr_sf_request_list(sid);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;ASSERT failed,'Other captain queue denied';
 j:=public.xr_sf_join_request(sid);rid2:=(j->'request'->>'id')::uuid;
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 j:=public.xr_sf_request_list(sid);ASSERT jsonb_array_length(j->'requests')=2,'Captain pending queue';
 ASSERT j::text LIKE '%"Rusher"%','Request role provided';
 j:=public.xr_sf_request_decide(ARRAY[rid,rid2],true);ASSERT (SELECT count(*) FROM public.squad_members WHERE squad_id=sid)=2,'Bulk acceptance respects cap';
 ASSERT (SELECT count(*) FROM public.xr_sf_join_requests WHERE id IN(rid,rid2) AND status='accepted')=1,'Only one approved';
 PERFORM set_config('request.jwt.claim.sub',b::text,true);
 IF NOT public.xr_sf_is_member(sid) THEN PERFORM set_config('request.jwt.claim.sub',c::text,true);END IF;
 ASSERT public.xr_sf_plan_get(sid)->'plan'->>'body'='Test plan','Member reads plan';
 ASSERT (public.xr_sf_member_ready(sid,true,'Rusher')->>'ok')::boolean,'Ready toggle';
 ASSERT (public.leave_squad()->>'ok')::boolean,'Legacy leave remains compatible';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 j:=public.xr_sf_invite_send(sid,d);ASSERT (j->>'ok')::boolean,j::text;iv:=(j->>'invite_id')::bigint;
 ASSERT (SELECT expires_at-created_at BETWEEN interval '29 seconds' AND interval '31 seconds' FROM public.squad_invites WHERE id=iv),'30s expiry';
 UPDATE public.squad_invites SET expires_at=now()-interval '1 second' WHERE id=iv;
 PERFORM set_config('request.jwt.claim.sub',d::text,true);
 ASSERT NOT (public.xr_sf_invite_respond(iv,true)->>'ok')::boolean,'Expired invite rejected';
 failed:=false;BEGIN PERFORM public.squad_invite_respond(iv,true);EXCEPTION WHEN OTHERS THEN failed:=true;END;ASSERT failed,'Legacy expired bypass blocked';
 ASSERT NOT EXISTS(SELECT 1 FROM public.squad_members WHERE user_id=d),'Expired did not join';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 j:=public.xr_sf_invite_send(sid,d);iv:=(j->>'invite_id')::bigint;
 PERFORM set_config('request.jwt.claim.sub',d::text,true);
 ASSERT jsonb_array_length(public.xr_sf_invite_list()->'invites')>=1,'Invite inbox';
 ASSERT (public.xr_sf_invite_respond(iv,true)->>'ok')::boolean,'Live invite accepted';
 ASSERT NOT (public.xr_sf_invite_respond(iv,true)->>'ok')::boolean,'No replay';
 PERFORM public.leave_squad();
 -- A second public squad exercises instant joining and the shared canonical membership guard.
 PERFORM set_config('request.jwt.claim.sub',e::text,true);INSERT INTO public.squad_creators(user_id) VALUES(e) ON CONFLICT DO NOTHING;
 j:=public.xr_sf_squad_create('__SF_PUBLIC_TEST_'||substr(e::text,1,8),'TEST',NULL,'public');sid2:=(j->>'id')::uuid;
 PERFORM set_config('request.jwt.claim.sub',f::text,true);ASSERT (public.xr_sf_join_public(sid2)->>'ok')::boolean,'Public instant join';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);j:=public.xr_sf_tryout_create('BR','Bermuda',10,sid);room:=(j->'room'->>'id')::uuid;ASSERT room IS NOT NULL,j::text;
 PERFORM set_config('request.jwt.claim.sub',b::text,true);ASSERT NOT (public.xr_sf_tryout_join(room)->>'ok')::boolean,'Private tryout membership';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);j:=public.xr_sf_tryout_create('BR','Bermuda',10,NULL);room:=(j->'room'->>'id')::uuid;
 PERFORM set_config('request.jwt.claim.sub',b::text,true);ASSERT (public.xr_sf_tryout_join(room)->>'ok')::boolean,'Tryout 2';
 PERFORM set_config('request.jwt.claim.sub',c::text,true);ASSERT (public.xr_sf_tryout_join(room)->>'ok')::boolean,'Tryout 3';
 PERFORM set_config('request.jwt.claim.sub',d::text,true);ASSERT (public.xr_sf_tryout_join(room)->>'ok')::boolean,'Tryout 4';
 PERFORM set_config('request.jwt.claim.sub',e::text,true);ASSERT NOT (public.xr_sf_tryout_join(room)->>'ok')::boolean,'Tryout cap 4';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);ASSERT public.xr_sf_tryout_mark_test(room)->>'test_source'='captain_recorded','Honest test marker';
 ASSERT (public.xr_sf_tryout_close(room)->>'ok')::boolean,'Host close';
 -- Opt-in free agent can receive capped in-app invitations; no notification/DM transport.
 PERFORM set_config('request.jwt.claim.sub',d::text,true);
 j:=public.xr_sf_player_preferences(jsonb_build_object('discoverable',true,'free_agent',true,'backup_opt_in',true,'available_from',now()-interval '1 minute','available_to',now()+interval '1 hour','availability_timezone','Asia/Kolkata'));
 ASSERT (j->>'ok')::boolean,j::text;
 PERFORM set_config('request.jwt.claim.sub',a::text,true);ASSERT (public.xr_sf_call_backup(sid)->>'ok')::boolean,'Backup call';ASSERT NOT (public.xr_sf_call_backup(sid)->>'ok')::boolean,'Backup five-minute limit';
 ASSERT EXISTS(SELECT 1 FROM public.squad_invites WHERE squad_id=sid AND invited=d AND source='sf' AND expires_at>now()),'Backup actual invite';
 -- No protected user details in SF results.
 j:=public.xr_sf_player_list();ASSERT j::text NOT LIKE '%ff_uid%' AND j::text NOT LIKE '%phone%' AND j::text NOT LIKE '%device%','No private identifiers';
 PERFORM set_config('request.jwt.claim.sub','',true);failed:=false;BEGIN PERFORM public.xr_sf_squad_list();EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;ASSERT failed,'Anonymous actor rejected';
END $test$;
-- RLS checks run as actual low-privilege roles, not only as SECURITY DEFINER owner.
SET LOCAL ROLE anon;
DO $rls$ BEGIN ASSERT NOT has_table_privilege(current_user,'public.xr_sf_trust_evidence','SELECT'),'Trust table not direct';ASSERT NOT has_function_privilege(current_user,'public.xr_sf_squad_list(text,text,boolean,integer)','EXECUTE'),'Anon RPC denied';ASSERT NOT has_function_privilege(current_user,'public.xr_sf_actor()','EXECUTE'),'Internal helper denied';END $rls$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $rls$ BEGIN ASSERT NOT has_table_privilege(current_user,'public.xr_sf_join_requests','SELECT'),'Private request table not direct';ASSERT NOT has_table_privilege(current_user,'public.xr_sf_player_prefs','UPDATE'),'Prefs via RPC only';ASSERT has_function_privilege(current_user,'public.xr_sf_squad_list(text,text,boolean,integer)','EXECUTE'),'SF RPC granted';END $rls$;
RESET ROLE;
DO $testsave$ BEGIN PERFORM set_config('sf.test.private_id',(SELECT id::text FROM public.squads WHERE name LIKE '__SF_PRIVATE_TEST_%' LIMIT 1),true);END $testsave$;
SET LOCAL ROLE anon;
DO $rls$ BEGIN
 ASSERT NOT EXISTS(SELECT 1 FROM public.squads WHERE id=current_setting('sf.test.private_id')::uuid),'Private squad RLS';
 ASSERT NOT EXISTS(SELECT 1 FROM public.squad_members WHERE squad_id=current_setting('sf.test.private_id')::uuid),'Private membership RLS';
END $rls$;
RESET ROLE;

ROLLBACK;
